from pathlib import Path
import json,math,html
D=Path(__file__).resolve().parent;OUT=D/'output';SRC=json.loads((D/'mezzanines.json').read_text(encoding='utf-8-sig'))
A=D.parents[1]/'Atlante_3D'
def url(p):return p.resolve().as_uri()
def it(v,n=2):return f'{v:.{n}f}'.replace('.',',')
def metric(c):
 x,y,w,h=c['deck'];sx,top,di,n,g,sw=c['flight'];z=c['level'];ss=.0254
 return dict(w=w*ss,h=h*ss,area=w*h*ss*ss,run=(n-1)*g,foot=(n-1)*g*sw,rise=z/n,over=4.20-z,under=z-c['depth'],goal=z+c['upperTarget'],guard=2*(w+h)*ss-sw,hand=2*math.hypot((n-1)*g,z-z/n))
program={
'P06':[
('01 · Bagno sul retro','Bagno di famiglia con doccia. Dal giardino lo si raggiunge rientrando nel ramo cucina. Verificare il filtro igienico tra i due vani.'),
('02 · Giardino chiuso','Tavolino e due sedute, vasi alle estremità. Conservare il percorso di uscita dalla cucina e l’accesso a scarichi e serramenti.'),
('03 · Cucina','Linea attrezzata sul lato lungo. Il pranzo è nel vano 4, vicino al verde, servito dal varco esistente.'),
('04 · Sala','Tavolo al retro. Oltre la quinta lignea si sale alla pedana con due poltrone. Dal livello basso si estraggono i cassetti.'),
('05–06 · Ingresso e servizi','Il 5 distribuisce zona giorno e notte. Il 6 ospita filtro, secondo servizio compatto e passaggio indipendente verso la camera singola.'),
('07–08 · Zona notte','Matrimoniale e singola sulla piazza con accessi separati. La nuova parete riprende P02. Misurare spallette, larghezza residua e caratteristiche del divisorio.'),
('Garage · G-B','Auto, banco e bici al piano terra con accesso dal vicolo. Il contenimento quotidiano resta al piano casa.'),
],
'P07':[
('01 · Bagno sul retro','Bagno con doccia accanto alla cucina. Gli impianti rimangono concentrati verso il retro.'),
('02 · Giardino chiuso','Due posti per la pausa dell’atelier, vegetazione bassa e schermo esterno. Misurare la luce disponibile alle scrivanie con la chiusura montata.'),
('03 · Cucina','Postazione lineare indipendente dall’atelier. Il pranzo di casa rimane nell’estremità della sala più vicina all’ingresso.'),
('04 · Sala e atelier','Due scrivanie a quota zero presso la finestra. Una porzione della quinta delimita la zona lavoro. Divano e tavolo sono al lato opposto della scala.'),
('05–06 · Ingresso e servizi','Una persona che arriva per lavorare passa dal 5 alla sala. La camera resta fuori dal percorso. Nel 6 sono previsti servizio e spazio tecnico.'),
('07–08 · Zona notte','Camera matrimoniale affacciata sulla piazza. Il vano a cuneo accoglie abiti e archivio domestico basso.'),
('Garage · G-B','Scaffali chiusi per materiali e due biciclette, lasciando separata la corsia dell’auto.'),
],
'P08':[
('01 · Bagno sul retro','Bagno principale con doccia. Verificare posizione della colonna e stato degli impianti prima di confermare le finiture.'),
('02 · Giardino chiuso','Giardino stagionale intero, separabile. Il salotto basso lo fronteggia attraverso la finestra esistente.'),
('03 · Cucina','Cucina a due banchi corti come in P04. Se la luce netta tra i fronti è insufficiente, il secondo banco si elimina.'),
('04 · Sala a due quote','Salotto vicino al giardino e tavolo da pranzo sotto il ballatoio. La scala sale lungo il fianco. Il nuovo piano raccoglie un’unica postazione di lavoro.'),
('05–06 · Ingresso e servizi','Dall’ingresso si arriva al pranzo sotto la struttura. Il ripostiglio centrale integra un secondo servizio se scarico e aerazione lo consentono.'),
('07–08 · Zona notte','Suite matrimoniale sulla piazza e guardaroba nel vano obliquo. La vita quotidiana può rimanere interamente al piano di ingresso.'),
('Garage · G-A','Autorimessa essenziale con scaffale mobile e una bici. La fattibilità dello studio alto si decide indipendentemente dal garage.'),
]}
notes={
'P06':('Vivere sopra un mobile','Il basamento è chiuso su tutta la sua altezza. Cassetti su guide pesanti si aprono dal fianco della sala. È una seduta sopraelevata accessibile con scala fissa, con un solo spazio destinato alle persone.','L’area superiore comprende lo sbarco. Lasciare una fascia libera di 0,90 × 0,90 m all’arrivo e disporre le sedute oltre questa fascia. Provare con mobili campione la manovra per estrarre i cassetti.','Confrontare il minimo intradosso su tutti i bordi con 3,96 m, obiettivo geometrico dato da 1,26 + 2,70. Se il margine locale è insufficiente, abbassare la pedana e ricalcolare il numero delle alzate.','Per la famiglia è la prima proposta da provare. Consente di mantenere due camere a terra e usa l’altezza senza richiedere due locali abitabili sovrapposti.'),
'P07':('Archiviare vicino all’atelier','Il ripiano superiore serve per riporre e riprendere saltuariamente campioni leggeri. Le due scrivanie per lavoro continuativo restano presso la finestra al piano inferiore. Il lato sotto l’impalcato ospita armadi bassi.','Lo sbarco è interamente sul piano da 5,64 m². Gli armadi non invadono lo sbarco o il bordo libero. Per i carichi dei campioni definire un peso massimo di progetto con lo strutturista.','Per questa prova si richiedono 2,00 m liberi sopra il calpestio, da convalidare anche per uso accessorio. Occorrono quindi 4,62 m sul percorso. Con il riferimento di 4,20 m mancano 42 cm. Se il rilievo conferma il deficit, mantenere l’archivio basso o su moduli estraibili dal basso.','Vale la pena proseguire solo dopo una sezione laser sulla parete laterale, dove la volta potrebbe essere più bassa che in chiave. Il limite può trovarsi già sugli ultimi gradini.'),
'P08':('Due usi abituali sovrapposti','La postazione di studio è disegnata per testarne l’ingombro. Sotto si continua a mangiare, sopra servirebbero luce, ventilazione e spazio per lavorare in piedi e seduti. Tutto il ballatoio è dentro l’involucro della casa.','Il tavolo inferiore si tiene lontano dai quattro appoggi ipotetici. Lo sbarco superiore conserva 0,90 × 0,90 m liberi. La camera del tour sopra l’impalcato è volutamente bassa per mostrare l’interferenza.','2,70 m sotto + 0,24 m di pacchetto + 2,70 m sopra = 5,64 m nello scenario ordinario di confronto. Con 4,20 m ne mancano 1,44. A questa altezza media lo studio abituale non è una base credibile per l’acquisto.','Se il rilievo conferma il limite, mantenere camera e cucina, sistemare la scrivania al piano principale nella sala e rinunciare al ballatoio. Non è previsto alcun innalzamento del tetto.')}
def table(cols,rows):return '<table><thead><tr>'+''.join('<th>'+c+'</th>' for c in cols)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table>'
def para(h,t):return f'<div class="para"><h3>{h}</h3><p>{t}</p></div>'
def picture(path,title,cls=''):return f'<figure class="{cls}"><img src="{url(path)}"><figcaption>{title}</figcaption></figure>'
def plate(id,suffix,title):return picture(OUT/'tavole'/f'{id}_{suffix}.svg',title,'plan')
pages=[]
def add(code,title,sub,body):
 page=len(pages)+1
 pages.append(f'<section><header><b>ARCHAI &nbsp; / &nbsp; CASATATOTATA</b><span>PALAZZO LOMBARDO &nbsp; · &nbsp; SAN GREGORIO DI CATANIA</span><b>{code}</b></header><h1>{title}</h1><p class="sub">{sub}</p>{body}<footer><span>CASA MARGHERITA 22 &nbsp; / &nbsp; STUDIO PRELIMINARE &nbsp; / &nbsp; R03</span><span>{page:02}</span></footer></section>')
add('Q00','Tre case, due quote','Appartamento al primo piano e autorimessa su Vico Piazza. Quaderno di progetto per la decisione prima dell’acquisto.',f'<div class="hero">{picture(A/"atmosfere/P06.webp","P06 · Interpretazione d’atmosfera del salotto rialzato. Geometria e quote alle tavole P06-L0, L1 e A–A.")}<div><small>CASA MARGHERITA 22</small><h2>Che cosa guadagna la casa salendo?</h2><p class="lead">P06 ricava contenimento sotto due poltrone. P07 porta in alto un archivio. P08 tenta di sovrapporre il luogo del lavoro a quello del pranzo.</p><p>Le tre piante principali includono camere, cucina, servizi, terrazzo e accesso. Per ognuna il secondo disegno mostra il solo piano alto, la scala e il vuoto sulla casa.</p><div class="box">Per voi partirei da P06. È l’unica delle tre che, usando 4,20 m come prova, lascia in alto più di 2,70 m. La verifica riguarda l’intera pedana e tutta la rampa.</div></div></div>')
rows=[]
for id,c in SRC.items():
 m=metric(c);rows.append([id,c['upperUse'],it(m['area'])+' m²','+'+it(c['level'])+' m',it(m['under'])+' m',it(m['over'])+' m',it(m['goal'])+' m'])
add('Q01','Il confronto in sezione','Il fascicolo catastale riporta 4,20 m di altezza media per la casa. Il valore non misura l’intradosso sopra uno specifico gradino.',
 table(['Casa','Uso alto','Impalcato¹','Quota finita','Libero sotto','Sopra se H=4,20','H di prova²'],rows)+'<div class="cols">'+para('P06 · margine geometrico di 24 cm','Con il riferimento medio, sopra la pedana restano 2,94 m. Il suo basamento contiene oggetti e non deve offrire altezza per camminare.')+para('P07 · deficit geometrico di 42 cm','Sopra il piano alto resterebbero 1,58 m. L’obiettivo progettuale di 2,00 m allo sbarco e nel percorso accessorio richiede un’altezza locale maggiore.')+para('P08 · deficit geometrico di 1,44 m','Sopra lo studio resterebbero 1,26 m. Il tavolo disegnato mostra dove si vorrebbe lavorare, ma l’uso abituale richiede una dimostrazione diversa e più severa.')+'</div><div class="box">¹ Impronta geometrica lorda del piano aggiunto, comprensiva dello sbarco. La scala occupa altro spazio al piano principale. Le superfici non si sommano ai 112 m² utili dichiarati per stimare una nuova superficie abitabile. &nbsp; ² H di prova è un obiettivo di sezione, non un titolo né una soglia comunale automaticamente applicabile.</div>')
for id,c in SRC.items():
 m=metric(c);pr=program[id];tag,below,access,rule,choice=notes[id]
 roomlist=''.join(para(h,t) for h,t in pr)
 add(id+' / L0 + L1',c['title'],c['description'],f'<div class="plans">{plate(id,"L0","L0 · Piano principale. Numeri corrispondenti ai vani del dossier R02. Tratteggio ruggine = proiezione del livello alto.")}{plate(id,"L1","L1 · Piano alto. Verde = superficie praticabile proposta. Retino chiaro = casa sottostante. Freccia = verso di salita.")}<div class="rooms">{roomlist}</div></div>')
 grade=n=c['flight'][3];g=c['flight'][4];stair=f'{n} alzate da {it(c["level"]/n*100,1)} cm · {n-1} pedate da {it(g*100,0)} cm · larghezza di progetto 90 cm'
 add(id+' / A–A',tag,'Sezione lungo la rampa nel verso di salita. La linea a 4,20 m è un riferimento medio. Sagoma umana convenzionale alta 1,70 m.',
 '<div class="halves"><div>'+picture(OUT/'tavole'/f'{id}_AA.svg','¹ Altezza di prova richiesta per l’obiettivo scelto, da verificare sull’intera superficie utilizzabile e lungo la rampa.','sectionFig')+
 table(['Elemento','Quantità di progetto'],[['Impalcato',f'{it(m["w"])} × {it(m["h"])} m = {it(m["area"])} m²'],['Scala',stair],['Proiezione della rampa',f'{it(m["run"])} × 0,90 m = {it(m["foot"])} m²'],['Pacchetto verticale',f'{it(c["depth"]*100,0)} cm, compresa finitura. Da dimensionare.']])+'</div><div>'+para('Sopra e sotto',below)+para('Percorso e sbarco',access)+para('Esito con le altezze disponibili',rule)+'<div class="box">'+choice+'</div></div></div>')
 add(id+' / VISTE','La casa dal piano principale al soppalco','Le tre viste sono calcolate dalla stessa geometria delle piante. Nel portale si può isolare il livello alto o guardare lo sbarco a 360°.',
 '<div class="renders">'+picture(A/'render'/f'{id}-spaccato.webp','Spaccato della casa completa. Le murature sono tagliate per leggere impalcato e scala.','whole')+'<div>'+picture(A/'render'/f'{id}-scala-giorno.webp','Dal piano principale · rapporto tra scala, arredi e luce.','smallrender')+picture(A/'render'/f'{id}-sopra-giorno.webp','Dal piano superiore · visuale indicativa. In P07 e P08 il punto di ripresa è volutamente basso.','smallrender')+'</div></div>')
rows=[]
for id,c in SRC.items():
 m=metric(c);rows.append([id,it(m['area'])+' m²',str(c['flight'][3])+' alzate',it(m['guard'])+' m',it(m['hand'])+' m',c['garage']])
add('Q11','Prima di scegliere la carpenteria','Portare al sopralluogo la pianta L1 e la sezione A–A della variante preferita. Far restituire le quote sullo stesso disegno.',
 '<div class="halves"><div>'+para('01 · Sezione reale','Rilevare piano finito, imposte, chiave e intradosso su una maglia ravvicinata. Misurare in verticale sopra ogni gradino, sulla linea del corrimano, allo sbarco e lungo il bordo della piattaforma. Controllare lampade, porte, travi e sopraluci.')+para('02 · Appoggi e struttura','Mappare orditure, volte, murature, piattabande e ambienti sottostanti. Verificare carichi concentrati e percorso dei carichi fino a terra, vibrazioni e risposta sismica. I montanti nei modelli indicano posizioni di studio. Una struttura indipendente deve comunque scaricare su appoggi verificati.')+para('03 · Uso, luce e tutela','Verificare la destinazione di ogni spazio, rapporti aeroilluminanti dopo la serra, larghezze nette, vie di esodo, parapetti, accessibilità e compatibilità con Palazzo Lombardo. Verificare separatamente il giardino chiuso e, per P07/P08, la possibilità di riconfigurare la quinta vetrata storica.')+'</div><div>'+table(['Variante','Piano alto','Scala','Protezione al bordo³','Corrimani rampa³','Garage abbinato'],rows)+para('Base per il preventivo','³ Sviluppi geometrici lordi del modello, prima di terminali, ritorni, fissaggi e compensazioni. Richiedere offerte separate per rilievi e pratiche, struttura e appoggi, scala/protezioni, ripristini e arredi. Evitare di sommare ai budget R01 sia la vecchia bauliera sia il nuovo sistema completo.')+para('Documenti di riferimento','NCV364 pp. 4, 11 e 13. Studio di dettaglio comunale, isolato 10, UE01, Palazzo Lombardo. Il REC, art. 95 c. 12, definisce il soppalco praticabile e richiama i requisiti igienico-sanitari. Il tecnico verifica la disciplina vigente e i pareri necessari sul fabbricato.')+'<p class="sources"><a href="https://win.comune.sangregoriodicatania.ct.it/newsArea.aspx?IDNew=134">Comune · studio del centro storico</a> &nbsp; / &nbsp; <a href="https://win.comune.sangregoriodicatania.ct.it/servicesg/RET%20con%20emendamenti%20commissione%20consiliare20230607103610421.pdf">REC comunale · art. 95</a></p></div></div>')
css="""@page{size:A3 landscape;margin:0}*{box-sizing:border-box}body{margin:0;font:14pt/1.38 'Segoe UI',Arial,sans-serif;color:#263f33;background:white;-webkit-print-color-adjust:exact;print-color-adjust:exact}section{width:420mm;height:296.9mm;padding:10mm 14mm 13mm;position:relative;overflow:hidden;break-after:page;background:#faf9f2}section:last-child{break-after:auto}header,footer{display:flex;justify-content:space-between;font-size:8.3pt;letter-spacing:1.8px;border-bottom:1px solid #bbc5b8;padding-bottom:3mm}footer{position:absolute;left:14mm;right:14mm;bottom:6mm;border:0;border-top:1px solid #bbc5b8;padding:2mm 0 0}h1,h2,h3{font-family:Georgia,serif;color:#264938}h1{font-size:37pt;line-height:1.06;letter-spacing:-1.5px;font-weight:400;margin:5mm 0 2mm}h2{font-size:31pt;font-weight:400;line-height:1.14;margin:6mm 0}h3{font-size:16.2pt;font-weight:500;margin:0 0 1mm}p{margin:0 0 3mm}.sub{font:16pt/1.38 Georgia,serif;color:#50675a;margin-bottom:5mm}.box{background:#e9e9db;border-left:3px solid #a96942;padding:4mm;font-size:13.1pt}.hero,.halves,.cols,.renders,.plans{display:grid;gap:7mm;align-items:start}.hero{grid-template-columns:1.64fr 1fr;align-items:center}.lead{font-size:19pt}.hero img{height:176mm;object-fit:cover}.hero small{letter-spacing:2px;color:#8e5f3b}.halves{grid-template-columns:1.02fr 1fr}.cols{grid-template-columns:repeat(3,1fr);margin:10mm 0}.para{border-top:1px solid #bdc6b9;padding-top:3mm;margin-bottom:3mm}.plans{grid-template-columns:.82fr .82fr 1.24fr}.rooms .para{padding-top:2.1mm;margin-bottom:1.8mm}.rooms p{font-size:12.5pt;margin:0}.rooms h3{font-size:14.6pt}.plan img{height:193mm}.sectionFig img{height:98mm}.renders{grid-template-columns:1.4fr 1fr;align-items:center}.whole img{height:170mm}.smallrender img{height:84mm}.smallrender{margin-bottom:4mm}figure{margin:0}figure img{width:100%;display:block;object-fit:contain;background:#f5f4ea}figcaption,.sources{font-size:10.4pt;color:#56695b;line-height:1.34;margin-top:2mm}a{color:#315c48}table{width:100%;border-collapse:collapse;margin:4mm 0;font-size:12.6pt}th{background:#315641;color:white;text-align:left;padding:2.8mm}td{padding:2.7mm;border-bottom:1px solid #d1d5c8;vertical-align:top}tbody tr:nth-child(even){background:#e9ede2}td:first-child{font-weight:600}"""
(OUT/'Due_quote.html').write_text('<!doctype html><html lang="it"><meta charset="utf-8"><title>Casa Margherita | Tre case, due quote</title><style>'+css+'</style><body>'+''.join(pages)+'</body></html>',encoding='utf8')
